python3 -c "
import json
with open('/app/resources/treasury_bulletin_2003_06.json') as f:
    data = json.load(f)

# Search for 'Congo' in the JSON
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')
    else:
        if 'Congo' in str(obj) or 'Zaire' in str(obj):
            print(f'{path}: {obj}')

search(data)
"
